function schedulePersistWorkspaceSession(){if(sessionPersistTimer)clearTimeout(sessionPersistTimer);sessionPersistTimer=setTimeout(async()=>{sessionPersistTimer=null;const result=await persistWorkspaceSession(true);if(result?.error&&!sessionPersistWarningShown){sessionPersistWarningShown=true;notify(`Recovery snapshot warning: ${result.error}`,'error',6500);}else if(!result?.error)sessionPersistWarningShown=false;},180);}
async function restoreWorkspaceSession(){if(!S.workspace?.path)return false;const loaded=await api('load_editor_session');if(loaded.error){notify(loaded.error,'error',4500);return false;}if(loaded.warning)notify(loaded.warning,'error',4500);const state=loaded.session;if(!state||state.version!==1||state.workspacePath!==S.workspace.path||!Array.isArray(state.openPaths))return false;if(state.breakpoints&&typeof state.breakpoints==='object'){const restoredBreakpoints=new Map();for(const [file,lines] of Object.entries(state.breakpoints))if(safeSessionPath(file)&&Array.isArray(lines))restoredBreakpoints.set(file,new Set(lines.map(Number).filter(n=>Number.isInteger(n)&&n>0&&n<=10000000).slice(0,2000)));S.debugBreakpoints=restoredBreakpoints;S.debugBreakpointConditions=new Map();if(state.breakpointConditions&&typeof state.breakpointConditions==='object')for(const [file,rows] of Object.entries(state.breakpointConditions)){if(!safeSessionPath(file)||!rows||typeof rows!=='object')continue;const points=restoredBreakpoints.get(file)||new Set(),entries=Object.entries(rows).filter(([line,value])=>Number.isInteger(Number(line))&&points.has(Number(line))&&typeof value==='string'&&value.trim()&&value.length<=300&&!/[\r\n\0]/.test(value));if(entries.length)S.debugBreakpointConditions.set(file,new Map(entries.map(([line,value])=>[Number(line),value.trim()])));}S.breakpointWorkspace=S.workspace.path;persistBreakpoints();}if(Array.isArray(state.debugWatches)){S.debugWatches=state.debugWatches.filter(x=>typeof x==='string'&&x.trim()&&x.length<=500).slice(0,30);S.watchWorkspace=S.workspace.path;}const paths=[...new Set(state.openPaths.filter(safeSessionPath))].slice(-SESSION_MAX_TABS);if(!paths.length){persistBreakpoints();persistDebugWatches();return false;}const drafts=state.drafts&&typeof state.drafts==='object'?state.drafts:{};let recovered=0,changedOnDisk=0;for(const path of paths){const result=await api('read_file',path);const draft=drafts[path];const hasDraft=draft&&typeof draft.content==='string'&&typeof draft.saved==='string'&&draft.content.length<=5*1024*1024&&draft.saved.length<=5*1024*1024;const hasUnsavedDraft=hasDraft&&draft.content!==draft.saved;if(result.error&& !hasUnsavedDraft)continue;const saved=hasDraft?draft.saved:result.content;const content=hasDraft?draft.content:result.content;const savedHash=hasDraft&&typeof draft.savedHash==='string'?draft.savedHash:result.sha256||null;const tab={path,name:path.split('/').pop(),content,saved,dirty:content!==saved,modified:result.error?null:(result.modified||null),size:result.error?new Blob([content]).size:(result.size||0),savedHash,openedAt:Number(draft?.openedAt)||Date.now(),savedAt:null};S.tabs.set(path,tab);if(tab.dirty){S.dirty.add(path);scheduleAutoSave(path);recovered++;if(result.error||(savedHash&&result.sha256&&savedHash!==result.sha256))changedOnDisk++;}}if(!S.tabs.size)return false;const active=paths.includes(state.activePath)&&S.tabs.has(state.activePath)?state.activePath:[...S.tabs.keys()].at(-1);S.selected=active;activateTab(active);renderTree();schedulePersistWorkspaceSession();if(recovered){notify(`Recovered ${recovered} unsaved draft${recovered===1?'':'s'}.`,'success',4500);if(changedOnDisk)notify(`${changedOnDisk} recovered file(s) changed on disk; saving will open the conflict check.`, 'error',6000);}else notify(`Restored ${S.tabs.size} open tab${S.tabs.size===1?'':'s'}.`,'info',3000);return true;}
function renderTree() { if(!treeEl||!S.tree)return;treeEl.innerHTML='';const root=document.createElement('div');root.className='tree-row root-row';root.style.setProperty('--depth',0);root.innerHTML=`<span class="tree-caret ${S.expanded.has('')?'':'collapsed'}">⌄</span>${icon('',true)}<span class="tree-label">${esc(S.tree.name)}</span>`;root.title=S.workspace?.path||'';root.onclick=()=>{S.expanded.has('')?S.expanded.delete(''):S.expanded.add('');renderTree()};treeEl.append(root);if(S.expanded.has(''))(S.tree.children||[]).forEach(e=>drawEntry(e,1,treeEl));if(!(S.tree.children||[]).length)treeEl.insertAdjacentHTML('beforeend','<div class="muted pad">This folder is empty.</div>'); }
function drawEntry(entry,depth,parent) { const node=document.createElement('div');node.className='tree-node';const row=document.createElement('div');row.className='tree-row';row.style.setProperty('--depth',depth);row.dataset.path=entry.path;row.classList.toggle('selected',S.selected===entry.path);row.classList.toggle('current',S.active===entry.path);row.innerHTML=`<span class="tree-caret ${entry.is_dir?(S.expanded.has(entry.path)?'':'collapsed'):'empty'}">⌄</span>${icon(entry.path,entry.is_dir)}<span class="tree-label">${esc(entry.name)}</span>${S.dirty.has(entry.path)?'<span class="tree-dot"></span>':''}`;row.title=entry.path;row.onclick=async e=>{e.stopPropagation();S.selected=entry.path;if(entry.is_dir){S.expanded.has(entry.path)?S.expanded.delete(entry.path):S.expanded.add(entry.path);renderTree();}else{await openFile(entry.path);renderTree();}};row.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();S.selected=entry.path;renderTree();showTreeContext(e.clientX,e.clientY,entry);};node.append(row);if(entry.is_dir&&S.expanded.has(entry.path))(entry.children||[]).forEach(c=>drawEntry(c,depth+1,node));parent.append(node); }
async function openFile(path) { const diffOverlay=$('#gitDiffOverlay');if(diffOverlay&&!diffOverlay.classList.contains('hidden')){diffOverlay.classList.add('hidden');diffOverlay.innerHTML='';}if(S.tabs.has(path)){activateTab(path);return;}const data=await api('read_file',path);if(data.error){notify(data.error,'error',4500);return;}S.tabs.set(path,{path,name:path.split('/').pop(),content:data.content,saved:data.content,dirty:false,modified:data.modified||null,size:data.size||0,savedHash:data.sha256||null,openedAt:Date.now(),savedAt:null});S.selected=path;activateTab(path);renderTree();schedulePersistWorkspaceSession(); }
