function modal(title,description,placeholder,confirmText,mode,path=''){S.modal=mode;S.modalPath=path;$('#modalTitle').textContent=title;$('#modalDescription').textContent=description;$('#modalInput').value='';$('#modalInput').placeholder=placeholder;$('#modalConfirm').textContent=confirmText;$('#modalOverlay').classList.remove('hidden');setTimeout(()=>$('#modalInput').focus(),20);}
function closeModal(){ $('#modalOverlay').classList.add('hidden');S.modal=null; }
function createEntry(kind,parent){const p=parent!==undefined?parent:(S.selected?(isDirectory(S.selected)?S.selected:parentPath(S.selected)):'');modal(kind==='folder'?'New Folder':'New File',`Create a ${kind==='folder'?'folder':'file'} inside the selected location.`,kind==='folder'?'folder-name':'filename.py',kind==='folder'?'Create Folder':'Create',kind==='folder'?'new-folder':'new-file',p||'');}
async function submitModal(e){e.preventDefault();const value=$('#modalInput').value.trim();if(!value)return;const mode=S.modal,path=S.modalPath;closeModal();if(mode==='new-file'||mode==='new-folder'){const result=await api('create_entry',path,value,mode==='new-folder');if(result.error){notify(result.error,'error');return;}if(result.entry?.is_dir)S.expanded.add(result.entry.path);await refreshWorkspace();notify(`${mode==='new-folder'?'Folder':'File'} created`,'success');if(!result.entry?.is_dir)openFile(result.entry.path);}else if(mode==='rename'){const result=await api('rename_entry',path,value);if(result.error){notify(result.error,'error');return;}const old=result.old_path,neo=result.path;for(const p of [...S.tabs.keys()]){if(p===old||p.startsWith(old+'/')){const tab=S.tabs.get(p),next=neo+p.slice(old.length);S.tabs.delete(p);tab.path=next;tab.name=next.split('/').pop();S.tabs.set(next,tab);if(S.active===p)S.active=next;if(S.selected===p)S.selected=next;}}await refreshWorkspace();renderTabs();renderBreadcrumbs();renderTree();notify('Renamed successfully','success');}}
async function renameSelected(){const entry=findEntry(S.tree,S.selected);if(entry)modal('Rename Item',`Rename “${entry.name}”.`,'New name','Rename','rename',entry.path);}
async function deleteEntry(path){const entry=findEntry(S.tree,path);if(!entry||!confirm(`Delete ${entry.is_dir?'folder':'file'} “${entry.name}”${entry.is_dir?' and its contents':''}? This cannot be undone.`))return;const result=await api('delete_entry',path);if(result.error){notify(result.error,'error');return;}for(const p of [...S.tabs.keys()])if(p===path||p.startsWith(path+'/')){S.tabs.delete(p);S.dirty.delete(p);if(S.active===p)S.active=null;}await refreshWorkspace();renderTabs();if(!S.active){const next=[...S.tabs.keys()].at(-1);next?activateTab(next):showWelcome();}notify('Deleted','success');}
