function copyText(text){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(text).then(()=>notify('Copied relative path','success')).catch(()=>notify(text));else notify(text);}
async function openWorkspace(){if(S.dirty.size&&!confirm('Discard unsaved changes and open another folder?'))return;await persistWorkspaceSession(S.dirty.size===0);const result=await api('pick_workspace');if(result.error){notify(result.error,'error',4500);return;}if(result.cancelled)return;if(S.debugRunning)await stopActiveDebugger();await stopTerminalSession();S.tabs.clear();S.dirty.clear();S.active=null;S.selected='';S.expanded=new Set(['']);await refreshWorkspace();const hadSession=await restoreWorkspaceSession();if(!hadSession)showWelcome();await startTerminalSession();notify(`Opened ${result.name}`,'success');}
