 S.pendingSaveConflict={path,tab,disk:disk.error?null:disk};
 if(!S.panel){S.panel=true;$('#bottomPanel').classList.remove('closed');}
 setBottomTab('output');const panel=$('#plainPanel');
 const localText=tab.content||code.value,diskText=disk.error?`Disk version unavailable: ${disk.error}`:disk.content;
 const limit=60000,truncate=text=>text.length>limit?text.slice(0,limit)+'\n… truncated for display …':text;
