function persistDebugWatches(){if(!S.watchWorkspace)return;try{window.localStorage.setItem('flowcode-watches:'+S.watchWorkspace,JSON.stringify(S.debugWatches));}catch(_){}schedulePersistWorkspaceSession(); }
function renderDebugWatches(){
 const box=$('#debugWatchPanel');if(!box)return;box.innerHTML='';
 if(!S.debugWatches.length){box.innerHTML='<p class="term-muted small">Add an expression to evaluate whenever execution pauses.</p>';return;}
 S.debugWatches.forEach(expression=>{const result=S.debugWatchResults.get(expression)||{value:S.debugIsPaused?'Not evaluated':'Waiting for pause'};const row=document.createElement('div');row.className='debug-watch-item';row.innerHTML=`<div class="debug-watch-top"><code>${esc(expression)}</code><button class="debug-watch-remove" title="Remove watch" aria-label="Remove watch">×</button></div><div class="debug-watch-value ${result.error?'term-error':''}">${esc(result.error||result.value||'undefined')}</div>`;row.querySelector('.debug-watch-remove').onclick=()=>{S.debugWatches=S.debugWatches.filter(x=>x!==expression);S.debugWatchResults.delete(expression);persistDebugWatches();renderDebugWatches();};box.append(row);});
}
async function addDebugWatch(){
 const input=$('#debugWatchInput'),expression=(input?.value||'').trim();if(!expression){notify('Enter an expression to watch.');input?.focus();return;}
 if(expression.length>500||/\r|\n/.test(expression)){notify('Watch expressions must be a single line up to 500 characters.','error');return;}
 if(!S.debugWatches.includes(expression)){if(S.debugWatches.length>=30){notify('A maximum of 30 watch expressions is supported.','error');return;}S.debugWatches.push(expression);persistDebugWatches();}
 if(input)input.value='';S.debugWatchResults.set(expression,{value:S.debugIsPaused?'Evaluating…':'Waiting for pause'});renderDebugWatches();if(S.debugIsPaused)await evaluateDebugWatch(expression);
}
async function evaluateDebugWatch(expression){
 if(!S.debugRunning||!S.debugIsPaused){S.debugWatchResults.set(expression,{value:'Waiting for pause'});renderDebugWatches();return;}
 S.debugWatchResults.set(expression,{value:'Evaluating…'});renderDebugWatches();
 const endpoint=S.debugEngine==='node'?'node_debug_command':'debug_command';
 const result=await api(endpoint,`evaluate ${expression}`);
 if(result.error){S.debugWatchResults.set(expression,{value:'',error:result.error});}
 else if(S.debugEngine==='node'&&Object.prototype.hasOwnProperty.call(result,'value')){S.debugWatchResults.set(expression,{value:result.value});}
 renderDebugWatches();
}
async function evaluateDebugWatches(){for(const expression of [...S.debugWatches])await evaluateDebugWatch(expression);}

async function refreshDebugConfigurations(){
 if(!S.active)return;
 const active=S.active,previousPath=S.debugConfigPath;
 const select=$('#debugConfigSelect');
 const prior=previousPath===active?(select?.value||S.selectedDebugConfigId):'';
 const result=await api('list_debug_configurations',active);
 if(S.active!==active)return;
 S.debugConfigurations=result.configurations||[];S.debugConfigPath=active;
 const priorStillExists=prior&&S.debugConfigurations.some(config=>config.id===prior);
 if(select){
  select.innerHTML='<option value="">Current file (default)</option>';
  for(const config of S.debugConfigurations){const option=document.createElement('option');option.value=config.id;option.textContent=`${config.name} · ${config.type} · ${config.program}`;select.append(option);}
  select.value=priorStillExists?prior:(S.debugConfigurations[0]?.id||'');
  S.selectedDebugConfigId=select.value;
 }else{
  S.selectedDebugConfigId=priorStillExists?prior:(S.debugConfigurations[0]?.id||'');
 }
 const info=$('#debugConfigInfo');if(info){if(result.errors?.length){info.textContent=`${result.errors.length} launch configuration(s) skipped. Check .vscode/launch.json.`;info.title=result.errors.join('\n');}else{info.textContent=S.debugConfigurations.length?`${S.debugConfigurations.length} launch configuration(s) loaded.`:'No .vscode/launch.json configurations; current file defaults are available.';info.title='';}}updateDebugConfigButtons();
}
function onDebugConfigurationChanged(){S.selectedDebugConfigId=$('#debugConfigSelect')?.value||'';updateDebugConfigButtons();}
function updateDebugConfigButtons(){const id=$('#debugConfigSelect')?.value||'';const found=S.debugConfigurations.some(config=>config.id===id);const edit=$('#editDebugConfig'),remove=$('#deleteDebugConfig');if(edit)edit.disabled=!found;if(remove)remove.disabled=!found;}
function openDebugConfigEditor(mode){if(!S.active){notify('Open a source file before editing launch configurations.');return;}const id=$('#debugConfigSelect')?.value||S.selectedDebugConfigId;const existing=S.debugConfigurations.find(config=>config.id===id);if(mode==='update'&&!existing){notify('Select a launch configuration to edit.');return;}S.debugConfigMode=mode;S.debugConfigEditingId=mode==='update'?existing.id:'';const cfg=existing||{};const isPython=mode==='create'?!['js','cjs','mjs'].includes(ext(S.active)):cfg.type==='python';$('#debugConfigFormTitle').textContent=mode==='create'?'New Launch Configuration':'Edit Launch Configuration';$('#debugConfigName').value=cfg.name||(isPython?`Python: ${S.active.split('/').pop()}`:`Node: ${S.active.split('/').pop()}`);$('#debugConfigType').value=cfg.type||(isPython?'python':'node');$('#debugConfigProgram').value=cfg.program||S.active;$('#debugConfigCwd').value=cfg.cwd||'${workspaceFolder}';$('#debugConfigArgs').value=JSON.stringify(cfg.args||[]);$('#debugConfigEnv').value=JSON.stringify(cfg.env||{});$('#debugConfigRuntimeArgs').value=JSON.stringify(cfg.runtimeArgs||[]);$('#debugConfigEditor').classList.remove('hidden');}
function closeDebugConfigEditor(){$('#debugConfigEditor')?.classList.add('hidden');S.debugConfigMode='';S.debugConfigEditingId='';}
async function saveDebugConfigEditor(event){event.preventDefault();let args,env,runtimeArgs;try{args=JSON.parse($('#debugConfigArgs').value||'[]');env=JSON.parse($('#debugConfigEnv').value||'{}');runtimeArgs=JSON.parse($('#debugConfigRuntimeArgs').value||'[]');}catch(error){notify(`Invalid JSON in arguments/environment: ${error.message}`,'error',4500);return;}if(!Array.isArray(args)||!env||Array.isArray(env)||typeof env!=='object'||!Array.isArray(runtimeArgs)){notify('Arguments and runtime arguments must be JSON arrays; environment must be a JSON object.','error',4500);return;}const configuration={name:$('#debugConfigName').value.trim(),type:$('#debugConfigType').value,request:'launch',program:$('#debugConfigProgram').value.trim(),cwd:$('#debugConfigCwd').value.trim(),args,env,runtimeArgs};const operation=S.debugConfigMode||'create',button=$('#saveDebugConfig');button.disabled=true;const result=await api('save_debug_configuration',operation,configuration,S.active,S.debugConfigEditingId);button.disabled=false;if(result.error){notify(result.error,'error',5000);return;}closeDebugConfigEditor();await refreshDebugConfigurations();if(result.id&&S.debugConfigurations.some(config=>config.id===result.id)){$('#debugConfigSelect').value=result.id;onDebugConfigurationChanged();}notify(`Launch configuration ${operation==='create'?'created': 'saved'}.`,'success',2500);}
async function deleteDebugConfiguration(){const id=$('#debugConfigSelect')?.value||S.selectedDebugConfigId;const config=S.debugConfigurations.find(item=>item.id===id);if(!config){notify('Select a launch configuration to delete.');return;}if(!confirm(`Delete launch configuration “${config.name}”?`))return;const result=await api('save_debug_configuration','delete',{},S.active,id);if(result.error){notify(result.error,'error',5000);return;}closeDebugConfigEditor();await refreshDebugConfigurations();notify('Launch configuration deleted.','success',2500);}

async function stopActiveDebugger(){
 if(!S.debugRunning)return;
 const endpoint=S.debugEngine==='node'?'node_debug_stop':'debug_stop';
 await api(endpoint);S.debugRunning=false;S.debugIsPaused=false;S.debugLine=null;S.debugLocals={};
 if(S.debugTimer){clearInterval(S.debugTimer);S.debugTimer=null;}
 renderEditor();renderDebugVariables();renderDebugConsole();
}
async function startDebugger(){
 if(!S.active){notify('Open a Python or JavaScript file before starting the debugger.');return;}
 if(S.debugConfigPath!==S.active)await refreshDebugConfigurations();
 const select=$('#debugConfigSelect'),selectedId=select?select.value:S.selectedDebugConfigId;
 const launchConfiguration=S.debugConfigurations.find(config=>config.id===selectedId)||null;
 const originalActive=S.active;
 if(S.dirty.size){
  if(!confirm('Save all open changes before starting the debugger?'))return;
  for(const path of [...S.dirty]){if(!S.tabs.has(path))continue;activateTab(path);await saveActive();if(S.dirty.has(path)){notify(`Could not save ${path}; debugging cancelled.`,'error',4500);if(S.tabs.has(originalActive))activateTab(originalActive);return;}}
  if(S.tabs.has(originalActive))activateTab(originalActive);
 }
 const file=launchConfiguration?.program||S.active;
 if(file!==S.active)await openFile(file);
 const extension=ext(file),isPython=launchConfiguration?launchConfiguration.type==='python':extension==='py',isNode=launchConfiguration?launchConfiguration.type==='node':['js','cjs','mjs'].includes(extension);
 if(!isPython&&!isNode){notify('The selected launch configuration must target Python or Node.js JavaScript.','error',5000);return;}
 if(S.dirty.has(file)){await saveActive();if(S.dirty.has(file)){notify('Save the target file before debugging.','error',4500);return;}}
 if(S.debugRunning)await stopActiveDebugger();
 if(!S.panel){S.panel=true;$('#bottomPanel').classList.remove('closed');}
 setActivity('run');setBottomTab('debug');
 if(S.debugTimer){clearInterval(S.debugTimer);S.debugTimer=null;}
 const points=[...(S.debugBreakpoints.get(file)||new Set())];
 const engine=isPython?'python':'node',endpoint=isPython?'debug_start':'node_debug_start';
 const conditions=Object.fromEntries([...(S.debugBreakpointConditions.get(file)||new Map())].filter(([line,expression])=>points.includes(line)&&typeof expression==='string'&&expression.trim()).map(([line,expression])=>[String(line),expression]));const result=isPython?await api(endpoint,file,points,launchConfiguration,conditions):await api(endpoint,file,points,launchConfiguration);
 if(result.error){notify(result.error,'error',5000);return;}
 S.debugEngine=engine;S.debugRunning=true;S.debugIsPaused=false;S.debugFile=file;S.debugLine=null;S.debugLocals={};S.debugMessages=[];
 appendDebugMessage(`Started ${isPython?'Python bdb':'Node.js Inspector'} debugger: ${file}${launchConfiguration?` · ${launchConfiguration.name}`:''} (${result.engine||engine}).`,'term-muted');
 renderDebugVariables();renderDebugWatches();renderEditor();
 S.debugTimer=setInterval(pollDebugger,140);await pollDebugger();
}
async function sendDebugCommand(command){
 if(!S.debugRunning){notify('No active debug session. Open a supported Python or JavaScript file and start debugging.');return;}
 const endpoint=S.debugEngine==='node'?'node_debug_command':'debug_command';
 if(['continue','step','next'].includes(command))S.debugIsPaused=false;if(command==='stop')S.debugIsPaused=false;
 const result=await api(endpoint,command);
 if(result.error)notify(result.error,'error',4000);
 else if(command==='stop')appendDebugMessage('Stop requested.','term-muted');
}
async function pollDebugger(){
 if(!S.debugRunning)return;
 const endpoint=S.debugEngine==='node'?'node_debug_poll':'debug_poll';
 const result=await api(endpoint);
 if(result.error){appendDebugMessage(result.error,'term-error');S.debugRunning=false;}
 for(const event of result.events||[]){
  if(event.type==='watch'){S.debugWatchResults.set(event.expression,{value:event.value||'',error:event.error||null});renderDebugWatches();}
  else if(event.type==='console'){appendDebugMessage(event.text||'','term-output');}
  else if(event.type==='exception'){
   appendDebugMessage(event.message||'Program exception','term-error');
   if(event.traceback)appendDebugMessage(event.traceback,'term-error');
  }else if(event.type==='stopped'||event.type==='locals'){
   if(event.type==='stopped')S.debugIsPaused=true;
   S.debugLocals=event.locals||{};S.debugLine=Number(event.line)||null;S.debugFile=event.file||S.debugFile;
   appendDebugMessage(`Paused (${event.reason||'inspect'}) · ${event.file||''}:${event.line||'?'} · ${event.function||''}`,'term-muted');
   if(S.debugFile&& !S.debugFile.startsWith('../') && !S.debugFile.startsWith('..\\') && findEntry(S.tree,S.debugFile)&&!isDirectory(S.debugFile)){
    if(S.active!==S.debugFile)await openFile(S.debugFile);
    renderEditor();if(S.debugLine)goToLine(S.debugLine);
   }
   renderDebugVariables();if(event.type==='stopped')await evaluateDebugWatches();
  }else if(event.type==='terminated'){S.debugIsPaused=false;
   appendDebugMessage(`${event.message||'Debug session ended'} (exit ${event.returncode??'?'})`,event.returncode===0?'term-muted':'term-error');
   S.debugRunning=false;S.debugIsPaused=false;S.debugLine=null;S.debugEngine=null;renderEditor();
  }
 }
 if(result.returncode!==null&&result.returncode!==undefined&&S.debugRunning){
  S.debugRunning=false;S.debugIsPaused=false;appendDebugMessage(`Debugger process exited with code ${result.returncode}.`,result.returncode===0?'term-muted':'term-error');S.debugLine=null;renderEditor();
 }else if(result.running===false&&S.debugRunning&&!((result.events||[]).some(event=>event.type==='terminated'))){
  S.debugRunning=false;S.debugIsPaused=false;S.debugLine=null;appendDebugMessage('Debug session ended.','term-muted');renderEditor();
 }
 if(!S.debugRunning&&S.debugTimer){clearInterval(S.debugTimer);S.debugTimer=null;S.debugEngine=null;renderDebugVariables();renderDebugConsole();}
}

async function searchWorkspace(query){const input=$('#workspaceQuery'),q=query??input?.value??'',withContent=$('#searchContents')?.checked??true;const result=await api('search_workspace',q,withContent);const box=$('#workspaceSearchResults');if(!box)return;box.innerHTML='';if(result.error){box.innerHTML=`<div class="muted pad">${esc(result.error)}</div>`;return;}if(!result.results?.length){box.innerHTML='<div class="muted pad">No results found.</div>';return;}for(const hit of result.results){const b=document.createElement('button');b.className='search-result';b.innerHTML=`<span>${hit.kind==='match'?'↳':'•'}</span><span><strong>${esc(hit.path)}${hit.line?':'+hit.line:''}</strong>${hit.preview?`<small>${esc(hit.preview)}</small>`:''}</span>`;b.onclick=async()=>{await openFile(hit.path);if(hit.line)goToLine(hit.line);};box.append(b);}}
function renderTestFileList(id,files){const box=$('#'+id);if(!box)return;box.replaceChildren();if(!files?.length){const empty=document.createElement('div');empty.className='muted small';empty.textContent='No test files discovered.';box.append(empty);return;}for(const path of files.slice(0,100)){const row=document.createElement('button');row.type='button';row.className='test-file-row';row.title=path;row.textContent=path;row.onclick=()=>openFile(path);box.append(row);}}
async function refreshTestExplorer(){const summary=$('#testSuiteSummary');if(summary)summary.textContent='Scanning workspace…';const result=await api('discover_workspace_tests');if(result.error){if(summary)summary.textContent=result.error;return;}if(summary)summary.textContent=`${result.python_count||0} Python · ${result.node_count||0} Node.js ${result.truncated?'· scan capped':''}`;const py=$('#pythonTestSummary'),node=$('#nodeTestSummary'),npm=$('#npmTestInfo');if(py)py.textContent=`${result.python_count||0} file(s) · runner: ${result.python_runner||'unittest'}`;if(node)node.textContent=`${result.node_count||0} test file(s) · Node ${result.node_available?'available':'not installed'}`;if(npm)npm.textContent=result.npm_test?`package.json script: test → ${result.npm_test_script||'(configured)'}`:'No scripts.test entry in package.json.';renderTestFileList('pythonTestFiles',result.python_files||[]);renderTestFileList('nodeTestFiles',result.node_files||[]);const pythonButton=$('#runPythonTests'),nodeButton=$('#runNodeTests'),npmButton=$('#runNpmTests');if(pythonButton)pythonButton.disabled=!(result.python_count>0);if(nodeButton)nodeButton.disabled=!(result.node_count>0&&result.node_available);if(npmButton)npmButton.disabled=!(result.npm_test&&result.npm_available);const output=$('#testRunResult');if(output&&result.warnings?.length){output.classList.remove('hidden');output.textContent=result.warnings.join('\n');}}
async function runWorkspaceTests(kind){if(S.dirty.size){await saveAll();if(S.dirty.size){notify('Test run cancelled because one or more editor files could not be saved.','error',5000);return;}}const ids={python:'#runPythonTests',node:'#runNodeTests',npm:'#runNpmTests'},button=$(ids[kind]),output=$('#testRunResult');if(button){button.disabled=true;button.textContent='Running tests…';}if(output){output.classList.remove('hidden');output.className='test-run-result running';output.textContent=`Running ${kind==='npm'?'npm test':kind==='node'?'Node.js tests':'Python tests'}…`; }const result=await api('run_workspace_tests',kind);if(button){button.disabled=false;button.textContent=kind==='python'?'▶ Run Python Tests':kind==='node'?'▶ Run Node Tests':'▶ Run npm test';}if(output){const succeeded=!result.error&&!result.timed_out&&result.returncode===0;output.className='test-run-result '+(succeeded?'passed':'failed');const details=[result.error||`${result.runner||kind} · exit code ${result.returncode}${result.timed_out?' · timed out':''}`,result.stdout||'',result.stderr||''].filter(Boolean).join('\n\n');output.textContent=(succeeded?'PASS\n':'FAIL\n')+details;output.scrollTop=0;}if(result.error){notify(result.error,'error',5500);}else if(result.returncode===0&&!result.timed_out){notify(`${result.runner||kind} completed successfully.`,'success',2500);}else{notify(`${result.runner||kind} failed with exit code ${result.returncode}.`,'error',3500);}await refreshTestExplorer();}

