function renderGitHunks(result){
 const box=$('#gitResults');if(!box)return;box.innerHTML='';
 if(result.error||result.returncode!==0){const pre=document.createElement('pre');pre.className='term-line term-error';pre.textContent=result.error||result.stderr||'Could not load Git hunks.';box.append(pre);return;}
 const title=document.createElement('div');title.className='git-hunks-title';title.textContent=`Hunk staging · ${result.path||''}`;box.append(title);
 const addGroup=(label,hunks,action)=>{
  const group=document.createElement('section');group.className='git-hunks-group';
  const heading=document.createElement('h4');heading.textContent=label;group.append(heading);
  if(!hunks?.length){const empty=document.createElement('p');empty.className='muted small';empty.textContent='No hunks in this section.';group.append(empty);box.append(group);return;}
  for(const hunk of hunks){
   const card=document.createElement('article');card.className='git-hunk-card';
   const top=document.createElement('div');top.className='git-hunk-top';
   const meta=document.createElement('div');meta.className='git-hunk-meta';
   const name=document.createElement('strong');name.textContent=`Hunk ${hunk.index+1} · +${hunk.additions} −${hunk.deletions}`;
   const range=document.createElement('code');range.textContent=hunk.header;meta.append(name,range);
   const actions=document.createElement('div');actions.className='git-hunk-actions';
   const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent=action==='stage-hunk'?'＋ Stage Hunk':'− Unstage Hunk';
   button.onclick=()=>gitAction(action,JSON.stringify({path:result.path,index:hunk.index,signature:hunk.signature}));actions.append(button);
   if(action==='stage-hunk'){const discard=document.createElement('button');discard.type='button';discard.className='secondary danger';discard.textContent='Discard Hunk';discard.onclick=()=>gitAction('discard-hunk',JSON.stringify({path:result.path,index:hunk.index,signature:hunk.signature}));actions.append(discard);}
   top.append(meta,actions);card.append(top);
   const preview=document.createElement('pre');preview.className='git-hunk-preview';preview.textContent=hunk.preview||'';card.append(preview);group.append(card);
  }
  box.append(group);
 };
 addGroup('Unstaged changes',result.unstaged_hunks,'stage-hunk');
 addGroup('Staged changes',result.staged_hunks,'unstage-hunk');
 if(result.unstaged_truncated||result.staged_truncated){const note=document.createElement('p');note.className='muted small';note.textContent='Only the first 200 hunks per section are available. Refresh after staging or editing.';box.append(note);}
}
function renderGitCompare(result){const panel=$('#gitDiffOverlay');if(!panel)return;panel.innerHTML='';panel.classList.remove('hidden');const header=document.createElement('div');header.className='git-diff-header';const meta=document.createElement('div');meta.className='git-diff-meta';const title=document.createElement('strong');title.textContent=`Compare · ${result.path||''}`;const labels=document.createElement('div');labels.className='git-diff-labels';const leftLabel=document.createElement('span');leftLabel.textContent=result.left_label||'HEAD';const rightLabel=document.createElement('span');rightLabel.textContent=result.right_label||'Working tree';labels.append(leftLabel,rightLabel);meta.append(title,labels);const close=document.createElement('button');close.type='button';close.className='secondary';close.id='gitDiffClose';close.textContent='Close';close.onclick=()=>{panel.classList.add('hidden');panel.innerHTML='';};header.append(meta,close);panel.append(header);const scroll=document.createElement('div');scroll.className='git-diff-scroll';const grid=document.createElement('div');grid.className='git-diff-grid';for(const row of result.rows||[]){for(const side of ['left','right']){const cell=document.createElement('div');cell.className=`git-diff-cell ${side} ${row.kind||'same'}${row[side]===undefined||row[side]===''?' blank':''}`;const lineNo=document.createElement('span');lineNo.className='git-diff-number';lineNo.textContent=row[side+'_no']===null||row[side+'_no']===undefined?'':String(row[side+'_no']);const line=document.createElement('span');line.className='git-diff-code';line.textContent=row[side]||' ';cell.append(lineNo,line);grid.append(cell);}}scroll.append(grid);panel.append(scroll);if(result.truncated){const note=document.createElement('div');note.className='git-diff-note';note.textContent='Diff is truncated by safety limits (1 MB per file, 2,500 lines per side, 1,500 aligned rows, 4,000 characters per line).';panel.append(note);}}
async function refreshTabsAfterGitSwitch(){const active=S.active;for(const [path,tab] of S.tabs){const loaded=await api('read_file',path);if(loaded.error){tab.missingOnDisk=true;continue;}tab.content=loaded.content;tab.saved=loaded.content;tab.dirty=false;tab.missingOnDisk=false;tab.savedHash=loaded.sha256||null;tab.modified=loaded.modified||null;tab.size=loaded.size||0;S.dirty.delete(path);}if(active&&S.tabs.has(active)){const tab=S.tabs.get(active);if(!tab.missingOnDisk){suppressMonacoChanges=true;code.value=tab.content;suppressMonacoChanges=false;renderEditor();renderOutline();await validateCurrent();}else notify(`${active} is not present in the new branch. Its tab was kept for recovery; reopen it after switching back.`,'error',6000);}renderTabs();renderTree();renderBreadcrumbs();renderTimeline();schedulePersistWorkspaceSession();}
async function gitAction(action,arg=''){const pathArg=String(arg||'').trim();if(['stage-hunk','unstage-hunk','discard-hunk'].includes(action)){try{const request=JSON.parse(arg);if(['stage-hunk','discard-hunk'].includes(action)&&S.dirty.has(request.path)){notify('Save this file before changing its Git hunks; Git operates on disk content.','error',5000);return;}}catch(_){notify('Invalid Git hunk request. Refresh the hunk list.','error');return;}if(action==='discard-hunk'&&!confirm(`Discard only the selected unstaged hunk in ${JSON.parse(arg).path}? This edits the file on disk and cannot be undone through FlowCode.`))return;}if(['branch-create','branch-switch','commit','pull','push','merge','merge-abort'].includes(action)&&S.dirty.size){notify('Save all unsaved editor tabs before this Git action. The Git operation was cancelled.','error',5000);return;}if(action==='add'&&S.dirty.size&&(pathArg==='.'||S.dirty.has(pathArg))){notify('Save the file before staging it; Git only stages content on disk.','error',5000);return;}if(['branch-create','branch-switch'].includes(action)&&!confirm(`${action==='branch-create'?'Create and switch to this branch':'Switch to the selected branch'}? Open clean tabs will reload from the selected branch.`))return;if(action==='merge'&&!confirm(`Merge branch "${pathArg}" into the current branch? Conflicts may require manual editing.`))return;if(action==='merge-abort'&&!confirm('Abort the current Git merge? Uncommitted merge resolution work may be discarded.'))return;if(action==='pull'&&!confirm('Pull the selected remote branch using fast-forward-only mode? Local changes are not overwritten by an automatic merge commit.'))return;if(action==='push'&&!confirm('Push the current local branch to the selected remote? No force-push will be used.'))return;const r=await api('git_action',action,arg);if(action==='status'){const statusBox=$('#gitStatusOutput');if(statusBox){statusBox.innerHTML='';const value=r.error||r.stderr||r.stdout||'No status output.';const pre=document.createElement('pre');pre.className=r.error||r.stderr?'term-error':'term-output';pre.textContent=value;statusBox.append(pre);}const list=$('#gitChangedFiles');if(list){list.innerHTML='';const files=Array.isArray(r.files)?r.files:[];if(!files.length){const empty=document.createElement('span');empty.className='muted';empty.textContent=r.error||r.returncode!==0?'Git status is unavailable.':'No changed files.';list.append(empty);}for(const item of files){const row=document.createElement('button');row.type='button';row.className='git-changed-file';row.title=item.path;const code=document.createElement('span');code.className='git-status-code';code.textContent=item.status;const path=document.createElement('span');path.className='git-changed-path';path.textContent=item.path;row.append(code,path);row.onclick=async()=>{const target=$('#gitPath');if(target)target.value=item.path;await gitAction('compare',JSON.stringify({path:item.path,old_path:item.original_path||item.path}));};list.append(row);}if(r.files_truncated){const note=document.createElement('span');note.className='muted';note.textContent='Showing first 300 changed files.';list.append(note);}}}else if(action==='branch-list'&&r.returncode===0){const select=$('#gitBranchSelect');if(select){const rows=(r.stdout||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean).map(line=>({current:line.startsWith('*'),name:line.replace(/^\*\s*/, '').trim()})).filter(item=>item.name);select.innerHTML='';if(!rows.length){select.add(new Option('No local branches yet',''));}for(const item of rows){const option=new Option(item.name,item.name);if(item.current)option.selected=true;select.add(option);}}}else if(action==='remote-list'&&r.returncode===0){const select=$('#gitRemoteSelect');if(select){const previous=select.value,rows=(r.stdout||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);select.innerHTML='';if(!rows.length)select.add(new Option('No remote configured',''));for(const remote of rows)select.add(new Option(remote,remote));if(rows.includes(previous))select.value=previous;else if(rows.length)select.value=rows[0];}}else if(action==='remote-branch-list'&&r.returncode===0){const select=$('#gitRemoteBranchSelect');if(select){const previous=select.value,rows=(r.stdout||'').split(/\r?\n/).map(x=>x.trim()).filter(x=>x&&!x.endsWith('/HEAD')&&!x.includes(' -> '));select.innerHTML='';if(!rows.length)select.add(new Option('No remote branch',''));for(const branch of rows)select.add(new Option(branch,branch));if(rows.includes(previous))select.value=previous;else if(rows.length)select.value=rows[0];}}else if(action==='compare'){if(r.error||r.returncode!==0){const box=$('#gitResults');if(box){box.innerHTML='';const pre=document.createElement('pre');pre.className='term-line term-error';pre.textContent=r.error||r.stderr||'Could not compare this file.';box.append(pre);}}else{renderGitCompare(r);}}else if(action==='hunks'){renderGitHunks(r);}else if(action==='conflicts'){const list=$('#gitConflictFiles');if(list){list.innerHTML='';const conflicts=Array.isArray(r.conflicts)?r.conflicts:[];if(r.error||r.returncode!==0){const item=document.createElement('span');item.className='muted';item.textContent=r.error||r.stderr||'Could not inspect conflicts.';list.append(item);}else if(!conflicts.length){const item=document.createElement('span');item.className='muted';item.textContent='No unresolved merge conflicts.';list.append(item);}for(const conflict of conflicts){const button=document.createElement('button');button.type='button';button.className='git-changed-file';button.title=conflict.path;const iconNode=document.createElement('span');iconNode.className='git-status-code';iconNode.textContent='UU';const label=document.createElement('span');label.className='git-changed-path';label.textContent=conflict.path;button.append(iconNode,label);button.onclick=async()=>{const tab=S.tabs.get(conflict.path);if(tab&&!tab.dirty){const latest=await api('read_file',conflict.path);if(!latest.error){tab.content=latest.content;tab.saved=latest.content;tab.savedHash=latest.sha256||null;tab.modified=latest.modified||null;tab.size=latest.size||0;}}await openFile(conflict.path);const marker=code.value.split('\n').findIndex(line=>/^(<<<<<<<|=======|>>>>>>>)/.test(line));if(marker>=0)goToLine(marker+1);};list.append(button);}}}else{const box=$('#gitResults');if(box){box.innerHTML='';for(const k of ['stdout','stderr','error'])if(r[k]){const pre=document.createElement('pre');pre.className='term-line '+(k==='error'||k==='stderr'?'term-error':'term-output');pre.style.whiteSpace='pre-wrap';pre.textContent=r[k];box.append(pre);}if(!r.stdout&&!r.stderr&&!r.error)box.textContent=r.returncode===0?'Done.':'Git command finished without output.';}}if(['merge','pull'].includes(action)&&r.returncode!==0&&!r.error){await gitAction('conflicts');}if(r.error){notify(r.error,'error',4500);return;}if(r.returncode===0){if(!['status','branch-list','remote-list','remote-branch-list','conflicts','compare','hunks'].includes(action))notify(`Git ${action} complete`,'success',1800);if(['init','add','unstage','stage-hunk','unstage-hunk','discard-hunk','commit','branch-create','branch-switch','merge','merge-abort','pull'].includes(action))await gitAction('status');if(['init','branch-create','branch-switch'].includes(action))await gitAction('branch-list');if(['init','fetch','remote-list','remote-add'].includes(action))await gitAction('remote-branch-list');if(['init','fetch'].includes(action))await gitAction('remote-list');if(['merge','merge-abort','pull'].includes(action))await gitAction('conflicts');if(['branch-create','branch-switch','merge','merge-abort','pull'].includes(action)){await refreshWorkspace();await refreshTabsAfterGitSwitch();if(['branch-create','branch-switch'].includes(action))await gitAction('branch-list');}if(action==='branch-create')$('#gitBranch').value='';if(action==='merge')$('#gitMergeBranch').value='';if(action==='commit')$('#gitMessage').value='';if(['stage-hunk','unstage-hunk','discard-hunk'].includes(action)){try{await gitAction('hunks',JSON.parse(arg).path);}catch(_){}}}}
