function renderOutline(){
 const box=$('#outlineContent');if(!box)return;box.innerHTML='';
 if(!S.active){box.textContent='Open a file to view symbols.';return;}
 const lines=code.value.split(String.fromCharCode(10)),fileExt=ext(S.active),items=[];
 for(let i=0;i<lines.length;i++){
  const line=lines[i];let item=null,m;
  if(fileExt==='py'){
   m=line.match(/^\s*(?:async\s+)?(def|class)\s+([A-Za-z_]\w*)/);
   if(m)item={type:m[1]==='class'?'class':'function',name:m[2],line:i+1};
  }else if(['js','jsx','ts','tsx','mjs','cjs'].includes(fileExt)){
   m=line.match(/^\s*(?:export\s+)?(?:default\s+)?(?:async\s+)?(function|class)\s+([A-Za-z_$][\w$]*)/);
   if(m)item={type:m[1]==='class'?'class':'function',name:m[2],line:i+1};
   else {m=line.match(/^\s*(?:export\s+)?(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?(?:function|\([^)]*\)\s*=>|[A-Za-z_$][\w$]*\s*=>)/);if(m)item={type:'function',name:m[1],line:i+1};}
  }else if(['html','htm'].includes(fileExt)){
   m=line.match(/<h([1-6])\b[^>]*>(.*?)<\/h\1>/i);if(m)item={type:'heading',name:m[2].replace(/<[^>]+>/g,'').trim()||`Heading ${m[1]}`,line:i+1};
  }else if(['css','scss'].includes(fileExt)){
   m=line.match(/^\s*([^@/][^{]+)\s*\{/);if(m)item={type:'selector',name:m[1].trim(),line:i+1};
  }
  if(item)items.push(item);
 }
 if(!items.length){box.textContent='No outline symbols found.';return;}
 items.slice(0,180).forEach(item=>{const b=document.createElement('button');b.className='outline-item';b.innerHTML=`<span>${item.type==='class'?'C':item.type==='function'?'ƒ':item.type==='heading'?'H':'◇'}</span><strong>${esc(item.name)}</strong><small>${item.line}</small>`;b.title=`${item.type} · line ${item.line}`;b.onclick=()=>goToLine(item.line);box.append(b);});
}
function renderTimeline(){const box=$('#timelineContent');if(!box)return;box.innerHTML='';if(!S.active){box.textContent='Select a file to view its session activity.';return;}const tab=S.tabs.get(S.active);if(!tab){box.textContent='No session activity.';return;}const events=[{label:'Opened in FlowCode',at:tab.openedAt},{label:tab.dirty?'Unsaved edits':'Saved buffer',at:tab.savedAt||tab.openedAt}];events.forEach(ev=>{const row=document.createElement('div');row.className='timeline-item';row.innerHTML=`<span class="timeline-dot"></span><div><strong>${esc(ev.label)}</strong><small>${new Date(ev.at).toLocaleTimeString()}</small></div>`;box.append(row);});const meta=document.createElement('div');meta.className='timeline-meta';meta.textContent=`${tab.size||new Blob([tab.content]).size} bytes · ${language(S.active)}`;box.append(meta);}
