 if(['JavaScript','TypeScript'].includes(language(S.active))){result=await api('typescript_intelligence',S.active,code.value,at.line,at.column,'references');if(!result.error)refs=result.references||[];else if(monacoEditor){monacoEditor.trigger('flowcode','editor.action.referenceSearch.trigger',{});return;}}
