async function openWorkspaceSymbolPicker(){
 const buffers={};for(const [path,tab] of S.tabs){if(['py','js','cjs','mjs','jsx','ts','tsx'].includes(ext(path)))buffers[path]=path===S.active?code.value:tab.content;}
 const result=await api('workspace_symbols',buffers);if(result.error){notify(result.error,'error',4500);return;}
 const symbols=result.symbols||[];if(!symbols.length){notify('No Python or JavaScript/TypeScript symbols were found in this workspace.');return;}
 const items=symbols.map(symbol=>({label:`${symbol.name} — ${symbol.path}:${symbol.line}  ${symbol.kind}${symbol.container?` · ${symbol.container}`:''}`,icon:symbol.kind==='class'?'◇':symbol.kind==='function'||symbol.kind==='async function'?'ƒ':symbol.kind==='interface'?'▧':'•',symbol,run:async()=>{await openFile(symbol.path);goToLine(symbol.line);}}));
 presentCommandPicker(items,'Type a symbol name, file, or container…','symbols');
 if(result.warnings?.length)notify(result.warnings[0],'info',4500);
}
