function openCommandPalette(quick=false){presentCommandPicker(quick?quickOpenItems():commandItems(),quick?'Type a file name to open…':'Type a command…',quick?'files':'commands');}
function filteredCommandItems(query){const q=query.trim().toLowerCase();if(S.commandMode!=='symbols')return S.commandItems.filter(i=>i.label.toLowerCase().includes(q));if(!q)return [...S.commandItems].sort((a,b)=>a.symbol.name.localeCompare(b.symbol.name)||a.symbol.path.localeCompare(b.symbol.path));const ranked=[];for(const item of S.commandItems){const s=item.symbol,text=`${s.name} ${s.qualified_name||s.name} ${s.path} ${s.kind} ${s.container||''}`.toLowerCase();let pos=0,score=0,last=-2,ok=true;for(const ch of q){const at=text.indexOf(ch,pos);if(at<0){ok=false;break;}score+=at===last+1?7:Math.max(1,5-(at-pos));if(at===0)score+=8;last=at;pos=at+1;}if(!ok)continue;if(s.name.toLowerCase().startsWith(q))score+=100;if(s.name.toLowerCase().includes(q))score+=45;if(s.path.toLowerCase().includes(q))score+=15;ranked.push({item,score});}return ranked.sort((a,b)=>b.score-a.score||a.item.symbol.name.localeCompare(b.item.symbol.name)).map(x=>x.item);}
function renderCommands(query){const box=$('#commandResults'),items=filteredCommandItems(query);S.visibleCommandItems=items;box.innerHTML='';if(!items.length){box.innerHTML='<div class="command-empty">No matching commands or files.</div>';return;}S.commandIndex=Math.max(0,Math.min(S.commandIndex,items.length-1));items.forEach((item,i)=>{const b=document.createElement('button');b.className='command-result '+(i===S.commandIndex?'selected':'');b.innerHTML=`<span class="result-icon">${esc(item.icon||'›')}</span><span>${esc(item.label)}</span><span class="result-shortcut">${esc(item.shortcut||'')}</span>`;b.onmouseenter=()=>{S.commandIndex=i;box.querySelector('.command-result.selected')?.classList.remove('selected');b.classList.add('selected');};b.onclick=()=>{closeCommandPalette();item.run();};box.append(b);});}
function executeCommand(){const q=$('#commandInput').value.trim(),item=S.visibleCommandItems[S.commandIndex];closeCommandPalette();if(item)item.run();else if(q&&S.commandMode!=='symbols')openFile(q);}
function closeCommandPalette(){$('#commandOverlay').classList.add('hidden');}
function openFind(replace=false){if(!S.active){notify('Open a file to search its contents.');return;}S.replaceMode=replace;$('#findWidget').classList.remove('hidden');$('#replaceInput').classList.toggle('hidden',!replace);$('#replaceOne').classList.toggle('hidden',!replace);$('#replaceAll').classList.toggle('hidden',!replace);$('#findInput').focus();$('#findInput').select();scanMatches();}
function scanMatches(){const q=$('#findInput').value;S.finds=[];S.findIndex=0;if(q){let i=0;while((i=code.value.toLowerCase().indexOf(q.toLowerCase(),i))!==-1){S.finds.push(i);i+=Math.max(1,q.length);}}$('#findCounter').textContent=S.finds.length?`${S.findIndex+1} of ${S.finds.length}`:'No results';if(S.finds.length)selectMatch();}
